  cycle_nudge_menstruation_warmth_body: "痛みはプロスタグランジンのしわざです。温めてゆっくり動くと、たいていの痛み止めと同じくらい和らぎます。この時期はエネルギーが低いのが自然なことです。",
  cycle_nudge_follicular_plan_headline: "*先の計画*を立てるのによい日",
  cycle_nudge_follicular_plan_body: "エストロゲンが増えると、集中力も気分も冴えてきます。この育てる時期に、むずかしい考えごとや大きめの運動、先延ばしにしていた会話を。",
  cycle_nudge_follicular_hydrate_headline: "*頸管粘液*を見てみて",
  cycle_nudge_follicular_hydrate_body: "チャンスの時期が近づくと、透明でよく伸びるようになってきます。粘液はほとんど水分。1日2〜2.5リットルの水分で、サインが見やすくなります。",
  cycle_nudge_ovulation_timing_headline: "*排卵の2日前*がいちばん大切",
  cycle_nudge_ovulation_timing_body: "精子は最大5日、卵子は12〜24時間だけ生きます。ぴったりの日より、その手前を大切に。回数のほうが正確さより効きます。",
  cycle_nudge_luteal_sleep_headline: "今週は*睡眠*を守って",
  cycle_nudge_luteal_sleep_body: "プロゲステロンで体温が上がり、眠りが浅くなりがちです。部屋を涼しくして早めに休む準備をすると、気分が思った以上に落ち着きます。",
  cycle_nudge_luteal_move_headline: "*ぐるぐる*には散歩が効きます",
  cycle_nudge_luteal_move_body: "黄体期後半の落ち込みはホルモンのせいで、あなたの人生への判決ではありません。日光を浴びながら20分動くと、スマホを見るよりずっと気持ちが切り替わります。",
  cycle_nudge_fertility_follicular_headline: "チャンスの時期が*近づいています*",
  cycle_nudge_fertility_follicular_body: "エストロゲンが排卵に向けて増えています。排卵前の5日間が妊娠しやすい期間で、精子はそれだけ卵子を待てます。",
  cycle_nudge_fertility_luteal_headline: "チャンスの時期は*終わりました*",
  cycle_nudge_fertility_luteal_body: "卵子は12〜24時間しか生きないので、この時期は妊娠しにくい時期です。検査やタイミングをとっていたなら、あとは待つだけです。",
  cycle_nudge_fertility_menstruation_headline: "*新しい*周期のはじまり",
  cycle_nudge_fertility_menstruation_body: "1日目で時計がリセットされます。次の妊娠しやすい期間はおよそ2週間後。始まる前に、ゆっくり休んで備えましょう。",
  cycle_nudge_reflect_mood_headline: "今日の*気分*はどう？",
  cycle_nudge_reflect_mood_body: "気分をさっと記録すると、全体像が少しずつ見えてきます。数周期分たまると、時期ごとの傾向が分かりやすくなります。",
  cycle_nudge_reflect_symptom_headline: "今日、*気になること*はありますか？",
  cycle_nudge_reflect_symptom_body: "腹痛、胸のはり、頭痛はありますか？症状を記録しておくと、あなたの普段の感じ方を、あなたと医師が見つけやすくなります。",
  cycle_nudge_reflect_energy_headline: "*エネルギー*はどのくらい？",
  cycle_nudge_reflect_energy_body: "生理前はエネルギーが下がるのが自然です。今日の分を記録しておくと、あらがうのではなく、自分のリズムに合わせて計画できます。",
  cycle_nudge_nutrition_luteal_headline: "*マグネシウム*をとりましょう",
  cycle_nudge_nutrition_luteal_body: "ダークチョコ、アーモンド、かぼちゃの種、バナナは、周期の後半の腹痛をやわらげ、気分を安定させます。複合炭水化物と合わせると、食欲もおさまりやすくなります。",
  cycle_nudge_nutrition_ovulation_headline: "*卵子*に栄養を",
  cycle_nudge_nutrition_ovulation_body: "ベリー、葉物野菜、ナッツなど抗酸化物質が豊富な食べ物は、卵子の質を支えます。排卵のころは、亜鉛（かぼちゃの種、ひよこ豆）がとくに大切です。",
  cycle_nudge_edu_menstruation_headline: "生理は*1日目*",
  cycle_nudge_edu_menstruation_body: "周期1日目は、少量の出血ではなく、本格的な出血が始まった日です。すべての予測はここから数えるので、正確に記録するほど精度が上がります。",
  cycle_nudge_edu_follicular_headline: "*ひとつ*の卵胞が選ばれる",
  cycle_nudge_edu_follicular_body: "周期ごとに複数の卵胞が育ち始めますが、成熟して卵子を排出するのはたいてい1つだけです。エストロゲンの増加がその選択を進めます。",
  cycle_nudge_edu_ovulation_headline: "*36時間*のできごと",
  cycle_nudge_edu_ovulation_body: "排卵そのものは短く、LHサージから約24〜36時間で起こります。だからLH検査薬は、排卵ではなくサージをとらえるタイミングで使います。",
  cycle_nudge_edu_luteal_headline: "*2週間*の待ち時間",
  cycle_nudge_edu_luteal_body: "黄体期はとても安定していて、周期の長さにかかわらず、たいてい12〜14日です。周期の違いは、ほとんど前半から生まれます。",
  cycle_pillar_fertility: "妊娠のきほん",
