  cycle_conf_calendar: "カレンダーをもとにした見込みです。今後3日間のBBTとLHを追加すると、予測がより確かになります。",
  cycle_conf_bbt_only: "カレンダーとBBTをもとにしています。LH検査を加えると、確かさが90%を超えます。",
  cycle_conf_bbt_lh: "カレンダー、BBT、LHをもとにしており、確かさは高めです。排卵後の体温変化を待って、ピークを確定します。",
  cycle_conf_shift_confirmed: "BBTの変化を確認しました。過去のピークは確定です。これからの時期は、まだカレンダーをもとにしています。",
