  dataTrans_never3: "プライベートなデータを第三者のAIの学習に使うこと。",
  dataTrans_never4: "アカウント削除後もデータを保管し続けること。",
  dataTrans_footer: "データは保存時も通信時も暗号化されています。プライバシーポリシー全文は、データとプライバシー → 法的情報 でいつでもお読みいただけます。",
  about_title: "grandma.appについて",
  about_tagline: "よく知っているあなたのおとも",
  about_missionTitle: "私たちの使命",
  about_missionBody: "妊活中から妊娠中、そして育児の最初の数年まで、すべての親のそばで、落ち着いて見守る存在になること。家族のように感じられる支えです。",
  about_expertiseTitle: "専門知識に基づいています",
  about_expertiseBody: "Grandmaのガイドは、産婦人科、助産師、小児科の知識をもとにしています。やさしい支えであって、かかりつけ医の代わりではありません。",
  about_privacyTitle: "プライバシーが最優先",
  about_privacyBody: "健康と家族のデータは、あなたのものです。何をなぜ集めているかを、そのままご覧いただけます。",
  about_privacyPolicy: "プライバシーポリシー",
