  help_title: "ヘルプとよくある質問",
  help_subtitle: "いつでもお手伝いします",
  help_searchPlaceholder: "何をお探しですか？",
  help_noResults: "見つかりませんでした。別の言葉をお試しいただくか、下からお問い合わせください。",
  help_stillStuck: "まだお困りですか？",
  help_stillStuckBody: "答えが見つかりませんか？チームが喜んでお手伝いします。",
  help_contactUs: "お問い合わせ",
  help_catStart: "はじめに",
  help_catAccount: "アカウントとデータ",
  help_catCare: "ケアサークル",
  help_catAi: "GrandmaAI",
  help_catBilling: "購読と支払い",
  help_catPrivacy: "プライバシー",
  help_q_modes: "道のりのモードとは？",
  help_a_modes: "grandma.appはあなたの今に合わせて変わります：周期（周期の記録・妊活）、妊娠、子育て（0〜5歳）、更年期。ジャーニーごとにホーム、記録する内容、Grandmaのアドバイスが変わります。",
  help_q_switchMode: "モードはどう切り替えますか？",
  help_a_switchMode: "設定タブを開き、「わたしの歩み」からジャーニーをタップしてください。データはジャーニーごとに保存されるので、切り替えても何も失われません。",
  help_q_logging: "記録はどうしますか？",
  help_a_logging: "ホーム画面かカレンダータブから記録できます。日付と記録する内容（生理、症状、気分、睡眠など）を選んでください。すべてカレンダーとノートに表示されます。",
  help_q_export: "データはどう書き出しますか？",
  help_a_export: "設定 → データとプライバシー → 保存しているデータ → 自分のデータをすべて書き出す へ進んでください。保存しているすべての内容を、機械で読めるJSON形式のコピーで受け取れます。",
  help_q_delete: "アカウントはどう削除しますか？",
  help_a_delete: "設定 → アカウント → アカウントを削除 です。データは当社のシステムから完全に消去され、元に戻せません。",
  help_q_password: "パスワードはどう変更しますか？",
  help_a_password: "設定 → アカウント → パスワードを変更 です。AppleやGoogleでログインしている場合は、そちらのアカウントでログインを管理してください。",
  help_q_invite: "ケアサークルにはどう招待しますか？",
  help_a_invite: "設定 → ケアサークル → 招待 です。パートナー、シッター、祖父母の方に、安全なリンクを送れます。あなたが決めた権限どおりに参加します。",
  help_q_permissions: "家族に見せる内容を決められますか？",
  help_a_permissions: "はい。家族ごとにあなたが権限を決めます。記録や健康の記録などを、誰が見られるか、追加できるかを選べます。アクセスはいつでも変更や取り消しができます。",
  help_q_grandma: "Grandmaって誰ですか？",
  help_a_grandma: "Grandmaは、Claudeを使ったAIのおともです。あなたの道のりをふまえて質問に答え、昼も夜も、あたたかく実用的なガイドをお届けします。",
  help_q_medical: "Grandmaのアドバイスは医療アドバイスですか？",
  help_a_medical: "いいえ。Grandmaがお届けするのは、やさしい学びのガイドで、診断や治療ではありません。医療に関する心配は、必ず医師、助産師、小児科医にご相談ください。",
  help_q_premium: "プレミアムには何が含まれますか？",
  help_a_premium: "スキャンとチャットが使い放題になり、インサイトとリマインドもすべて使えます。月払いか年払いを選べます。",
  help_q_cancel: "プレミアムはどう解約しますか？",
  help_a_cancel: "購読の管理や解約は、アプリストアのアカウント設定からいつでもできます。プレミアムの機能は、請求期間の終わりまで使えます。",
  help_q_dataSafe: "データは安全ですか？",
  help_a_dataSafe: "はい。データは通信時も保存時も暗号化され、行レベルのセキュリティで守られています。あなたと、あなたが選んだケアサークルだけがアクセスできます。",
  help_q_sell: "データを販売していますか？",
  help_a_sell: "いいえ、決して。個人データを販売することはなく、プライベートな健康データやお子さんのデータを第三者のAIの学習に使うこともありません。",
