  guidelines_intro: "grandma.appは、親どうしが本音で支え合う場所です。みんなが安心して過ごせるよう、いくつかの簡単なルールをお願いしています。",
  guidelines_rule1Title: "やさしく、敬意をもって",
  guidelines_rule1Body: "ここにいる人はみな、それぞれの道のりを歩んでいます。嫌がらせ、いじめ、ヘイトスピーチ、個人への攻撃はやめましょう。",
  guidelines_rule2Title: "プライバシーを守る",
