  sw2_leap19_name: "出来事",
  sw2_leap19_desc: "動作が順番に起こると理解する",
  sw2_leap19_brain: "この頃、赤ちゃんは世界を一つのぼんやりした景色ではなく、出来事の連なりとして感じはじめることがよくあります。動作には始まりと途中と終わりがあります。原因と結果を考えはじめるきっかけで、急に何もかもが面白く見えるのもそのためです。",
  sw2_leap19_tip: "いないいないばあのような、原因と結果が分かる簡単な遊びをしてみましょう。出来事には予想できる結果があると学んでいるところです。",
  sw2_leap19_ph0: "べったり甘える、下ろすと泣く、眠りが乱れる。新しいことが一度にたくさんあって、疲れやすいかもしれません。",
  sw2_leap19_ph1: "赤ちゃんは、ある動作のあとに何が起こるかを結びつけようと忙しくしていることが多いです。押したり、落としたり、じっと見たり。",
  sw2_leap19_ph2: "意図して手を伸ばすようになり、物がなくならないことも分かりはじめます。落とした物を探します。",
  sw2_leap19_sg0: "分離不安が強まる",
  sw2_leap19_sg1: "とても甘えん坊",
  sw2_leap19_sg2: "おもちゃが落ちると泣く",
  sw2_leap19_sg3: "お昼寝をいやがる",
  sw2_leap19_sg4: "かまってほしがる",
  sw2_leap19_sg5: "いつもの流れが崩れると不機嫌になる",
  sw2_leap19_sk0: "自分から手を伸ばしてつかむ",
  sw2_leap19_sk1: "おもちゃを振ったり叩いたりする",
  sw2_leap19_sk2: "遊びを覚える",
  sw2_leap19_sk3: "「上」「下」が分かる",
  sw2_leap19_sk4: "動く物を目で追う",
  sw2_leap19_sk5: "びっくりすることで笑う",
  sw2_leap19_ac0: "いないいないばあやかくれんぼ",
  sw2_leap19_ac1: "ボールを転がし合う",
  sw2_leap19_ac2: "原因と結果が分かる簡単なおもちゃ（押すと音が鳴る）",
  sw2_leap19_ac3: "毎日の流れを一つずつ声に出して伝える",
  sw2_leap5_name: "感覚の変化",
  sw2_leap5_desc: "赤ちゃんが、より豊かな感覚の世界を見つけます",
  sw2_leap5_brain: "この頃、赤ちゃんは五感からずっと多くのことを感じ取り始めるかもしれません。はっきり見え、豊かな音が聞こえ、体の新しい感覚も生まれます。たくさんの刺激でありながら、すばらしい時期でもあります。",
  sw2_leap5_ph0: "よく泣く、甘えたがる、眠りが浅いといったことはよくあります。赤ちゃんは新しい感覚の情報をたくさん受け取っているのかもしれません。",
  sw2_leap5_ph1: "赤ちゃんは新しい景色や音をたくさん取り込んでいます。ぐずりがピークに達してから落ち着くことがあります。",
  sw2_leap5_ph2: "新しい感覚への気づきが花開きます。起きている時間が長くなり、じっと見つめることが増えるでしょう。",
  sw2_leap5_sg0: "いつもより泣く",
  sw2_leap5_sg1: "ひっきりなしに飲みたがる",
  sw2_leap5_sg2: "なだめにくい",
  sw2_leap5_sg3: "そばにいたがる",
  sw2_leap5_sg4: "驚きやすい",
  sw2_leap5_sg5: "服を脱ぐのを嫌がる",
  sw2_leap5_sk0: "光や音に反応する",
  sw2_leap5_sk1: "視線の追い方がなめらかになる",
  sw2_leap5_sk2: "人に向けた笑顔が出始める",
  sw2_leap5_sk3: "目が覚めている時間が増える",
  sw2_leap5_sk4: "あなたの声のほうを向く",
  sw2_leap5_sk5: "コントラストの強い模様に気づく",
  sw2_leap5_ac0: "赤ちゃんを外向きに抱いて、部屋を見せてあげましょう",
  sw2_leap5_ac1: "白黒のコントラストが強いカードを見せましょう",
  sw2_leap5_ac2: "していることを声に出して話しかけましょう",
  sw2_leap5_ac3: "落ち着いているときに、やさしくマッサージを",
  sw2_leap5_tip: "今はスキンシップがとても大切です。抱っこ紐やゆったりした揺れが、ぐずる日の助けになるかもしれません。",
