  pregnancy_affirmationFallback_0: "あなたの体は、何をすればいいかちゃんと知っています。どうか信じてあげてください。",
  pregnancy_affirmationFallback_1: "あなたは自分で思うよりずっと強く、感じているよりずっと勇敢です。",
  pregnancy_affirmationFallback_2: "毎日、あなたは奇跡を育てています。あなたはすばらしい人です。",
  pregnancy_affirmationFallback_3: "今日は自分にやさしくしてあげましょう。あなたはもう十分がんばっています。",
  pregnancy_affirmationFallback_4: "赤ちゃんは、心臓の鼓動のたびにあなたの愛を感じています。",
  pregnancy_affirmationFallback_5: "あなたはこのために生まれてきました。あなたの直感は賢いのです。",
  pregnancy_affirmationFallback_6: "休むことも大切なこと。自分を労わることは、赤ちゃんを労わることです。",
  pregnancy_affirmationFallback_7: "あなたの気持ちはどれも自然なものです。命を育てるのは大変で、美しい仕事です。",
  pregnancy_affirmationFallback_8: "この旅はひとりではありません。あなたは支えられ、守られています。",
  pregnancy_affirmationFallback_9: "体の痛みも変化も、あなたの体がすばらしい仕事をしている証です。",
  pregnancy_affirmationFallback_10: "赤ちゃんへのいまの愛しさは、本物で力強いものです。",
  pregnancy_affirmationFallback_11: "あなたは今、まさにいるべき場所にいます。",
  pregnancy_affirmationFallback_12: "あなたの体は、ゼロからひとりの人間をつくりました。それはすばらしいことです。",
  pregnancy_affirmationFallback_13: "赤ちゃんはあなたの声を聞いて、安心しています。",
  pregnancy_affirmationFallback_14: "深呼吸をしましょう。あなたも赤ちゃんも大丈夫です。",
  pregnancy_affirmationFallback_15: "この流れを信じましょう。あなたの体と赤ちゃんは、ひとつに響き合っています。",
  pregnancy_affirmationFallback_16: "完璧でなくていいのです。赤ちゃんに必要なのは、あなたそのものです。",
  pregnancy_affirmationFallback_17: "今日はできたことを、どんなに小さくても認めてあげましょう。",
